\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{colortbl}
\pagestyle{empty}

% ── Dark Mode Color Theme ──
\definecolor{primary}{HTML}{58A6FF}      % GitHub blue
\definecolor{secondary}{HTML}{3FB950}    % GitHub green
\definecolor{accent}{HTML}{D29922}       % GitHub amber
\definecolor{purple}{HTML}{BC8CFF}       % purple for skills
\definecolor{redtag}{HTML}{F85149}       % red for memory
\definecolor{cyan}{HTML}{39D2C0}         % teal for new/other
\definecolor{bgposter}{HTML}{0D1117}     % GitHub dark bg
\definecolor{cardbg}{HTML}{161B22}       % card background
\definecolor{cardbg2}{HTML}{1C2128}      % card background alt
\definecolor{textlight}{HTML}{E6EDF3}    % primary text
\definecolor{textgray}{HTML}{8B949E}     % muted text
\definecolor{statbg}{HTML}{1C2128}       % stat callout background
\definecolor{tablerow1}{HTML}{161B22}    % table row even
\definecolor{tablerow2}{HTML}{1A1F28}    % table row odd
\definecolor{tableheader}{HTML}{21262D}   % table header bg
\definecolor{trendup}{HTML}{3FB950}       % green for up trend
\definecolor{trenddown}{HTML}{F85149}     % red for down trend
\definecolor{trendneutral}{HTML}{8B949E}  % gray for neutral
\definecolor{trendnew}{HTML}{58A6FF}      % blue for new entry
\definecolor{tagagent}{HTML}{58A6FF}      % agent frameworks tag
\definecolor{tagclaude}{HTML}{3FB950}     % claude code tag
\definecolor{tagutil}{HTML}{D29922}       % utilities tag
\definecolor{tagskill}{HTML}{BC8CFF}      % skills tag
\definecolor{tagmemory}{HTML}{F85149}     % memory tag
\definecolor{tagother}{HTML}{39D2C0}      % other tag

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{primary}$\blacktriangleright$}}

% ── Card styles for dark mode ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{primary},
    left=14pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={primary!40},
    valign=top,
  },
  greencard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{secondary},
    left=14pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={secondary!40},
    valign=top,
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{accent},
    left=14pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{42}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={accent!40},
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════════
% TITLE BAR (span=2, rows 0-3)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, colframe=cardbg, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{primary!60},
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{64}{76}\selectfont\bfseries\color{primary} Coding AI Leaderboard}\\[8pt]
  {\fontsize{30}{38}\selectfont\color{textgray} Top 20 Fastest-Rising Open-Source Repos on GitHub}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{textgray!60} Week of April 9--15, 2026 \hspace{2em} \color{textgray!50} Data: star-history.com}
}

% ═══════════════════════════════════════════════════════════════
% STAT BANNER (span=2, rows 3-5)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=16pt, right=16pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={1pt}{0pt}{cardbg2},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{primary!30}{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{primary} +9,715}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Top Weekly Gain}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray!60} hermes-agent}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!30}{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{secondary} $\sim$48k}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Total Stars}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray!60} Across Top 20}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent!30}{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{accent} 9}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Above 2k Stars}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray!60} Nearly half the board}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{purple!30}{statbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{purple} 5}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Claude Code Repos}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textgray!60} 25\% of the Top 20}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════════
% CATEGORY LEGEND (span=2, row 5 only, very compact)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=24pt, right=24pt, top=4pt, bottom=4pt,
  valign=center, halign=center,
]{name=legend, column=1, span=2, between=row5 and row6}{
  \centering
  {\fontsize{18}{22}\selectfont\color{textgray}%
  \textcolor{tagagent}{$\blacksquare$} Agent Frameworks \hspace{1.5em}
  \textcolor{tagclaude}{$\blacksquare$} Claude Code Ecosystem \hspace{1.5em}
  \textcolor{tagutil}{$\blacksquare$} AI Utilities \hspace{1.5em}
  \textcolor{tagskill}{$\blacksquare$} Skills \& Plugins \hspace{1.5em}
  \textcolor{tagmemory}{$\blacksquare$} Memory \hspace{1.5em}
  \textcolor{tagother}{$\blacksquare$} New / Other%
  }
}

% ═══════════════════════════════════════════════════════════════
% TOP 20 RANKING TABLE (span=2, rows 6-19) -- THE CENTERPIECE
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=top, halign=center,
]{name=ranking, column=1, span=2, between=row6 and row19}{
  \centering
  {\fontsize{32}{38}\selectfont\bfseries\color{primary} Full Weekly Top 20 Ranking}\\[10pt]

  \renewcommand{\arraystretch}{1.45}
  \fontsize{21}{27}\selectfont
  \begin{tabular}{>{\columncolor{cardbg2}}p{28mm} p{24mm} >{\ttfamily}p{230mm} r}
  \rowcolor{tableheader}
  \multicolumn{1}{>{\columncolor{tableheader}}l}{\color{primary}\bfseries\fontsize{22}{28}\selectfont\ \ \#\ Rank} &
  \multicolumn{1}{>{\columncolor{tableheader}}c}{\color{primary}\bfseries\fontsize{22}{28}\selectfont Trend} &
  \multicolumn{1}{>{\columncolor{tableheader}}l}{\color{primary}\bfseries\fontsize{22}{28}\selectfont Repository} &
  \multicolumn{1}{>{\columncolor{tableheader}}r}{\color{primary}\bfseries\fontsize{22}{28}\selectfont Weekly Stars\ \ } \\[2pt]
  \rowcolor{tablerow1}
  \textcolor{tagagent}{$\blacksquare$}\ \ {\bfseries 1} & \textcolor{trendneutral}{---} & {\color{textlight}NousResearch/hermes-agent} & {\bfseries\color{primary}+9,715} \\
  \rowcolor{tablerow2}
  \textcolor{tagskill}{$\blacksquare$}\ \ {\bfseries 2} & \textcolor{trendup}{$\blacktriangle$} & {\color{textlight}forrestchang/andrej-karpathy-skills} & {\bfseries\color{secondary}+4,917} \\
  \rowcolor{tablerow1}
  \textcolor{tagagent}{$\blacksquare$}\ \ {\bfseries 3} & \textcolor{trendneutral}{---} & {\color{textlight}JuliusBrussee/caveman} & {\bfseries\color{accent}+4,407} \\
  \rowcolor{tablerow2}
  \textcolor{tagmemory}{$\blacksquare$}\ \ {\bfseries 4} & \textcolor{trenddown}{$\blacktriangledown$} & {\color{textlight}MemPalace/mempalace} & {\bfseries\color{textlight}+3,524} \\
  \rowcolor{tablerow1}
  \textcolor{tagskill}{$\blacksquare$}\ \ {\bfseries 5} & \textcolor{trendneutral}{---} & {\color{textlight}VoltAgent/awesome-design-md} & {\bfseries\color{textlight}+3,246} \\
  \rowcolor{tablerow2}
  \textcolor{tagutil}{$\blacksquare$}\ \ {\bfseries 6} & \textcolor{trendup}{$\blacktriangle$} & {\color{textlight}microsoft/markitdown} & {\bfseries\color{textlight}+3,048} \\
  \rowcolor{tablerow1}
  \textcolor{tagutil}{$\blacksquare$}\ \ {\bfseries 7} & \textcolor{trenddown}{$\blacktriangledown$} & {\color{textlight}safishamsi/graphify} & {\bfseries\color{textlight}+2,763} \\
  \rowcolor{tablerow2}
  \textcolor{tagagent}{$\blacksquare$}\ \ {\bfseries 8} & \textcolor{trendup}{$\blacktriangle$} & {\color{textlight}obra/superpowers} & {\color{textlight}+2,180} \\
  \rowcolor{tablerow1}
  \textcolor{tagclaude}{$\blacksquare$}\ \ {\bfseries 9} & \textcolor{trendup}{$\blacktriangle$} & {\color{textlight}shanraisshan/claude-code-best-practice} & {\color{textlight}+2,151} \\
  \rowcolor{tablerow2}
  \textcolor{tagclaude}{$\blacksquare$}\ \ {\bfseries 10} & \textcolor{trendneutral}{---} & {\color{textlight}affaan-m/everything-claude-code} & {\color{textlight}+1,978} \\
  \rowcolor{tablerow1}
  \textcolor{tagclaude}{$\blacksquare$}\ \ {\bfseries 11} & \textcolor{trendup}{$\blacktriangle$} & {\color{textlight}thedotmack/claude-mem} & {\color{textlight}+1,828} \\
  \rowcolor{tablerow2}
  \textcolor{tagutil}{$\blacksquare$}\ \ {\bfseries 12} & \textcolor{trenddown}{$\blacktriangledown$} & {\color{textlight}santifer/career-ops} & {\color{textlight}+1,788} \\
  \rowcolor{tablerow1}
  \textcolor{tagagent}{$\blacksquare$}\ \ {\bfseries 13} & \textcolor{trendup}{$\blacktriangle$} & {\color{textlight}multica-ai/multica} & {\color{textlight}+1,506} \\
  \rowcolor{tablerow2}
  \textcolor{tagagent}{$\blacksquare$}\ \ {\bfseries 14} & \textcolor{trendup}{$\blacktriangle$} & {\color{textlight}shiyu-coder/Kronos} & {\color{textlight}+1,286} \\
  \rowcolor{tablerow1}
  \textcolor{tagclaude}{$\blacksquare$}\ \ {\bfseries 15} & \textcolor{trenddown}{$\blacktriangledown$} & {\color{textlight}ultraworkers/claw-code} & {\color{textlight}+1,285} \\
  \rowcolor{tablerow2}
  \textcolor{tagclaude}{$\blacksquare$}\ \ {\bfseries 16} & \textcolor{trenddown}{$\blacktriangledown$} & {\color{textlight}openclaw/openclaw} & {\color{textlight}+1,268} \\
  \rowcolor{tablerow1}
  \textcolor{tagutil}{$\blacksquare$}\ \ {\bfseries 17} & \textcolor{trenddown}{$\blacktriangledown$} & {\color{textlight}OpenBMB/VoxCPM} & {\color{textlight}+1,266} \\
  \rowcolor{tablerow2}
  \textcolor{tagskill}{$\blacksquare$}\ \ {\bfseries 18} & \textcolor{trenddown}{$\blacktriangledown$} & {\color{textlight}addyosmani/agent-skills} & {\color{textlight}+1,195} \\
  \rowcolor{tablerow1}
  \textcolor{tagagent}{$\blacksquare$}\ \ {\bfseries 19} & \textcolor{trendneutral}{---} & {\color{textlight}rtk-ai/rtk} & {\color{textlight}+1,098} \\
  \rowcolor{tablerow2}
  \textcolor{tagother}{$\blacksquare$}\ \ {\bfseries 20} & \textcolor{trendnew}{\bfseries N} & {\color{textlight}garrytan/gstack} & {\color{textlight}+1,012} \\
  \end{tabular}
  \vspace{6pt}
}

% ═══════════════════════════════════════════════════════════════
% KEY TAKEAWAYS & TRENDS (span=2, rows 19-bottom)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=24pt, right=24pt, top=12pt, bottom=12pt,
  valign=center, halign=center,
  borderline north={2pt}{0pt}{primary!40},
]{name=takeaways, column=1, span=2, between=row19 and bottom}{
  \centering
  {\fontsize{22}{28}\selectfont\color{textlight}
  \textcolor{primary}{$\blacktriangleright$}\ \ {\bfseries Agent-first dev is surging} --
  hermes-agent's +9,715 stars dwarfs the field, leading 6 agent repos in the Top 20\hspace{0.8em}$\cdot$\hspace{0.8em}
  \textcolor{secondary}{$\blacktriangleright$}\ \ {\bfseries Claude Code ecosystem explodes} --
  5 repos, 8,500+ stars, 25\% of the leaderboard\hspace{0.8em}$\cdot$\hspace{0.8em}
  \textcolor{accent}{$\blacktriangleright$}\ \ {\bfseries Utilities hold strong} --
  markitdown, graphify show infrastructure still wins big%
  }
}

\end{tcbposter}
\end{document}

